#!/usr/bin/env python3
# =============================================================================
# emit_bridge.py — generate JtBridgeTable.h from params.yaml
# -----------------------------------------------------------------------------
# THE PROBLEM THIS FIXES
#   JtBridgeTable.h carries a "GENERATED by tools/gen_params.py. DO NOT
#   HAND-EDIT." banner and a note that CI runs --check. Neither was true:
#   gen_params.py has no bridge emitter, so the file has been hand-maintained
#   behind a banner claiming otherwise. That is worse than an honestly manual
#   file, because it invites trust it has not earned - and it is where the
#   arpeggiator quietly went missing.
#
# WHAT THE TABLE IS
#   The v1 controller keeps a 7-bit, CC-keyed internal model; only the wire
#   speaks NRPN. This table is the translation seam, both directions:
#
#       kByV1Cc     sorted by v1 CC     — UI knows the CC, the wire wants a ParamID
#       kByParamId  sorted by ParamID   — inbound NRPN, reverse lookup
#
#   Both are emitted sorted so a consumer can binary-search either direction.
#
# WHERE v1_cc COMES FROM
#   Recovered from the existing hand-maintained table and CCDefinitions.h, then
#   written into params.yaml as `v1_cc` so it becomes source rather than
#   derived. 143 recovered; 17 allocated for parameters that never had a
#   binding — the arpeggiator and the sequencer's aux lane.
#
#   New bindings are allocated ABOVE the existing range (204+). Below 128 a v1
#   CC is indistinguishable from a real MIDI controller number; the legacy model
#   already runs to 203, so appending keeps every new binding unmistakably
#   internal.
#
# WIRING IT IN
#   Add to gen_params.py's main():
#
#       from emit_bridge import emit_bridge, BRIDGE_PATH
#       ok &= write_if_changed(BRIDGE_PATH, emit_bridge(doc), args.check)
#
#   Then the banner is true, and --check enforces it.
# =============================================================================

import os

BRIDGE_PATH = os.path.join("gen", "JtBridgeTable.h")

# A v1 CC below this is in real MIDI controller territory; above it the number
# is unambiguously the legacy controller's own.
V1_INTERNAL_BASE = 128


def emit_bridge(doc):
    params = doc["params"]

    missing = [p["key"] for p in params if "v1_cc" not in p]
    if missing:
        raise ValueError("params.yaml: %d parameters have no v1_cc: %s"
                         % (len(missing), ", ".join(missing[:8])))

    seen = {}
    for p in params:
        cc = int(p["v1_cc"])
        if cc in seen:
            raise ValueError("v1_cc %d used by both %s and %s"
                             % (cc, seen[cc], p["key"]))
        seen[cc] = p["key"]

    by_cc = sorted(params, key=lambda p: int(p["v1_cc"]))
    by_id = sorted(params, key=lambda p: int(p["id"]))
    n = len(params)

    L = []
    a = L.append
    a("// " + "=" * 75)
    a("// JtBridgeTable.h — GENERATED by tools/gen_params.py.  DO NOT HAND-EDIT.")
    a("// " + "=" * 75)
    a("// v1-CC <-> v2-ParamID bridge for the ESP32 controller and the JUCE")
    a("// plugin.  Both keep a 7-bit, v1-CC-keyed internal model; only the wire")
    a("// speaks NRPN.  This table is the translation seam, both directions.")
    a("//")
    a("// CI runs `gen_params.py --check` — hand edits here fail the build.")
    a("// (Previously this banner was aspirational: no emitter existed and the")
    a("//  file was maintained by hand, which is how 17 parameters went missing.)")
    a("//")
    a("// v1 CCs at or above %d are internal to the legacy controller and cannot"
      % V1_INTERNAL_BASE)
    a("// be confused with a MIDI controller number.")
    a("// " + "=" * 75)
    a("#pragma once")
    a("")
    a("#include <stdint.h>")
    a("#include <stddef.h>")
    a("")
    a("namespace JtBridge {")
    a("")
    a("struct Entry { uint16_t v1cc; uint16_t paramId; };")
    a("")
    a(f"static constexpr size_t kCount = {n};")
    a(f"static constexpr uint16_t kV1InternalBase = {V1_INTERNAL_BASE};")
    a("")
    a("// Sorted by v1cc — outbound lookups (UI knows v1cc, wire wants ParamID).")
    a(f"static constexpr Entry kByV1Cc[kCount] = {{")
    for p in by_cc:
        a("    { %4d, 0x%04X },   // %s" % (int(p["v1_cc"]), p["id"], p["key"]))
    a("};")
    a("")
    a("// Sorted by paramId — inbound lookups (wire gives ParamID, UI wants v1cc).")
    a(f"static constexpr Entry kByParamId[kCount] = {{")
    for p in by_id:
        a("    { %4d, 0x%04X },   // %s" % (int(p["v1_cc"]), p["id"], p["key"]))
    a("};")
    a("")
    a("// --- lookups ---------------------------------------------------------")
    a("// Binary search both ways. Returns 0xFFFF when there is no binding, which")
    a("// a caller must check: a parameter added to params.yaml without a v1_cc")
    a("// would otherwise silently map to entry zero.")
    a("static constexpr uint16_t kNoBinding = 0xFFFF;")
    a("")
    a("inline uint16_t paramIdForV1Cc(uint16_t cc)")
    a("{")
    a("    size_t lo = 0, hi = kCount;")
    a("    while (lo < hi)")
    a("    {")
    a("        const size_t mid = (lo + hi) / 2;")
    a("        if (kByV1Cc[mid].v1cc == cc) return kByV1Cc[mid].paramId;")
    a("        if (kByV1Cc[mid].v1cc <  cc) lo = mid + 1; else hi = mid;")
    a("    }")
    a("    return kNoBinding;")
    a("}")
    a("")
    a("inline uint16_t v1CcForParamId(uint16_t paramId)")
    a("{")
    a("    size_t lo = 0, hi = kCount;")
    a("    while (lo < hi)")
    a("    {")
    a("        const size_t mid = (lo + hi) / 2;")
    a("        if (kByParamId[mid].paramId == paramId) return kByParamId[mid].v1cc;")
    a("        if (kByParamId[mid].paramId <  paramId) lo = mid + 1; else hi = mid;")
    a("    }")
    a("    return kNoBinding;")
    a("}")
    a("")
    a("} // namespace JtBridge")
    return "\n".join(L) + "\n"


if __name__ == "__main__":
    import sys
    sys.path.insert(0, os.path.dirname(__file__))
    from gen_params import build_model
    doc = build_model()
    out = emit_bridge(doc)
    os.makedirs(os.path.dirname(BRIDGE_PATH), exist_ok=True)
    with open(BRIDGE_PATH, "w", encoding="utf-8", newline="\r\n") as f:
        f.write(out)
    print(f"{BRIDGE_PATH}: {len(doc['params'])} entries, "
          f"{len(out.splitlines())} lines")
